    "Reciprocity": {"Explanation": "The email offers a discount ($75 off) if the recipient orders during the specified period, creating a sense of reciprocity where the recipient feels they should take advantage of the offer in return for the company's generosity."},
    "Scarcity": {"Explanation": "The email implies scarcity by mentioning a limited-time offer ('placed from February 15th thru 18th') and a limited number of eligible products ('totaling $699 or more'), creating a sense of urgency to act quickly."},
    "Authority": {"Explanation": "Not present. There is no mention of a recognized institution, title, or role that lends authority to the message."},
    "Commitment/Consistency": {"Explanation": "Not present. The email does not reference prior behavior or choices to push further action."},
    "Liking": {"Explanation": "Not present. The email does not use familiarity, flattery, or personalization to build trust or rapport."},
    "Social proof": {"Explanation": "Not present. The email does not reference other people's participation or endorsements to influence the recipient's decision-making process."}
}

