    "Scarcity": {"Explanation": "The email implies urgency by stating 'Immediate Action Required' and 'critical step to protect our shared work', creating a sense of scarcity and the need to act quickly."},
    "Authority": {"Explanation": "The email establishes authority through the use of the sender's title ('Senior Environmental Engineer') and the recognition of the recipient's past contributions ('your expertise and recent work on the recent Venice flood mitigation report')."},
    "Commitment/Consistency": {"Explanation": "The email references the recipient's past actions and contributions ('you\u2019ve been instrumental in maintaining our systems and data integrity during your time here'), which can be seen as a commitment to the organization, pushing them to continue this pattern of action."},
    "Liking": {"Explanation": "The email does not directly use familiarity, flattery, or personalization to build trust or rapport with the recipient."},
    "Social proof": {"Explanation": "The email does not reference other people's participation or endorsement to create social proof."}
}

